import boto3
from typing import Dict

def extract_kv_pairs(document_path: str) -> Dict[str, str]:
    """
    Extracts key-value pairs from a form-like document using Amazon Textract.
    Supports images (JPEG, PNG) and single-page PDFs.
    """
    textract = boto3.client('textract', region_name='us-east-1')

    with open(document_path, 'rb') as file:
        document_bytes = bytearray(file.read())

    response = textract.analyze_document(
        Document={'Bytes': document_bytes},
        FeatureTypes=['FORMS']
    )

    blocks = response['Blocks']
    block_map = {block['Id']: block for block in blocks}

    def get_text(block_id: str) -> str:
        block = block_map[block_id]
        text = ''
        if 'Relationships' in block:
            for relationship in block['Relationships']:
                if relationship['Type'] == 'CHILD':
                    for child_id in relationship['Ids']:
                        child = block_map[child_id]
                        if child['BlockType'] == 'WORD':
                            text += child['Text'] + ' '
        return text.strip()

    kv_pairs = {}
    for block in blocks:
        if block['BlockType'] == 'KEY_VALUE_SET' and 'KEY' in block['EntityTypes']:
            key_text = get_text(block['Id'])
            if 'Relationships' in block:
                for relationship in block['Relationships']:
                    if relationship['Type'] == 'VALUE':
                        for value_id in relationship['Ids']:
                            value_text = get_text(value_id)
                            kv_pairs[key_text] = value_text
                            break  # Assume one value per key
                        break
    return kv_pairs
